2	"""Patch copied cuda_tile bytecode sources for cross-LLVM i1 compatibility.
3	
4	The checked-out TileIR sources remain unchanged. This compatibility bridge is
5	applied only to the clean build copy and can be removed once the bytecode
6	boundary is stable across the LLVM versions used by Triton and tileiras.
7	"""
8	
9	from __future__ import annotations
10	
11	from pathlib import Path
12	import sys
13	
14	
15	def patch_writer(path: Path) -> None:
16	    text = path.read_text()
17	    helper_old = """/// Helper function to serialize the APFloat representation of a FloatAttr.
18	static void writeAPFloatRepresentation(const APFloat &apFloat,
19	                                       EncodingWriter &writer) {
20	  writeAPInt(apFloat.bitcastToAPInt(), writer);
21	}
22	"""
23	    helper_new = helper_old + """
24	/// Serialize i1 dense elements using a stable packed-bits format instead of
25	/// LLVM's version-dependent raw storage layout.
26	static void packI1DenseElements(DenseElementsAttr denseAttr,
27	                                SmallVectorImpl<char> &packedData) {
28	  assert(denseAttr.getElementType().isInteger(1) &&
29	         "expected i1 dense elements attribute");
30	  if (denseAttr.isSplat()) {
31	    packedData.resize(1);
32	    packedData[0] = denseAttr.getSplatValue<APInt>().isZero() ? 0x00 : 0xFF;
33	    return;
34	  }
35	  size_t numElements = denseAttr.getNumElements();
36	  packedData.assign(llvm::divideCeil(numElements, size_t{8}), 0);
37	  size_t idx = 0;
38	  for (const APInt &value : denseAttr.getValues<APInt>()) {
39	    if (!value.isZero())
40	      packedData[idx / 8] |= static_cast<char>(1u << (idx % 8));
41	    ++idx;
42	  }
43	}
44	"""
45	    serialize_old = """  LogicalResult serializeAttribute(Attribute attr, EncodingWriter &writer) {
46	    if (auto denseAttr = dyn_cast<DenseElementsAttr>(attr)) {
47	      // Get the raw data buffer in little-endian format.
48	      ArrayRef<char> rawData = denseAttr.getRawData();
49	"""
